CLIP['spear_shield'].setdefault('a2', 'Shield push and thrust. The shield is pushed forward into the target first; then the spear is thrust straight past the edge of the shield, point first; the reach is held behind the shield.'); CLIP['dual'].setdefault('b2', 'Two quick thrusts, one with each weapon. The right weapon is thrust straight forward, then the left one; a short hold with both weapons forward.'); CLIP['sickle'].setdefault('b2', 'Leaping downward strike. He crouches, jumps with the sickle raised, and brings it straight down on the target as he lands; a short hold low.')

CLIP['sickle'].setdefault('a1', 'Hooking cut. The sickle is drawn back outside the right shoulder and cut inward across the target in a wide arc, hooking toward the body; it carries through to the left; a short hold.'); CLIP['sickle'].setdefault('a2', 'Rising hook. The sickle drops low beside the right leg and is swept up through the target in a wide arc, finishing high; a short hold.'); CLIP['command'].setdefault('b2', 'Level command. The sword is swept out level from the left to the front in a wide arc and stops pointing at the target; he holds the point on it.')

CLIP['spear_shield'].setdefault('c3', 'Shield uppercut and downward thrust. The shield is swung up into the target from below; then the spear is raised and driven down over the top of the shield, point first; the reach is held low.'); CLIP['spear_shield'].setdefault('c4', 'Leaping downward thrust. He crouches behind the shield, jumps, and drives the spear straight down on the target as he lands; a short hold low behind the shield.'); CLIP['dual'].setdefault('c4', 'Rising double cut from a low hidden guard. Both weapons are held low behind the body, the knees bend, and they are cut upward through the target one after the other as the body rises; they finish high.')

CLIP['flexible'].setdefault('s1', 'Leaping lash. He springs forward low and fast and lashes the target as he lands; the weapon carries through and is drawn back.'); CLIP['command'].setdefault('a2', 'Raised command. The sword is lifted high above the head and swept down to point at the target; he holds the point on it.'); CLIP['dual'].setdefault('s5', 'Block and counter. One weapon is raised to block in front of the body; the other cuts across the target in a wide arc straight after; a short hold.'); CLIP['mounted_blade'].setdefault('s5', 'Three mounted cuts in a row. The weapon comes down on the target three times, lifted halfway between the cuts; the horse stamps its right forehoof with each cut; a hold low after the third.'); CLIP['mounted_blade'].setdefault('s6', 'Deep mounted cut. The horse sits far back on its haunches while the weapon is laid back over the right shoulder; then horse and rider surge forward and the weapon comes down in one big cut; a long hold low.'); CLIP['mounted_spear'].setdefault('s6', 'Deep mounted strike. The horse sits far back on its haunches while the spear is raised; then horse and rider surge forward and the spear comes down in one big strike; a long hold low.'); CLIP['heavy'].setdefault('s4', 'Ground smash. The heavy weapon is heaved up over the head with both hands and brought straight down into the ground in front; the body drops with it; a long hold low.'); CLIP['heavy'].setdefault('s5', 'Swing and smash. A wide level swing from the right across the front, carried round and up, then straight down onto the target; a long hold low.')

# big moves offered as basic attacks (cN = sN, snappy.py): wording for the ones the types did not have yet
for (_f, _s), _t in {('sword', 's6'): 'Spinning cut. The body winds to the right with the sword drawn back, then makes one full turn on the spot with the sword held out level, and the blade comes round onto the target; a short hold facing forward.', ('sword', 's1'): 'Rising cut from a low hidden guard. The sword is held low behind the body, the knees bend, and it is cut upward through the target as the body rises; it finishes high.', ('foot_spear', 's6'): 'Whirlwind spear. The upper body winds to the right and the spear is laid level; then one full turn on a low hop with the spear held out level, the point sweeping past the front; he lands facing forward.', ('spear_shield', 's6'): 'Turning thrust. The body turns once on the spot behind the shield and comes out of the turn into a straight thrust, point first; the reach is held behind the shield.', ('dual', 's6'): 'Spinning double cut. The body winds, makes one full turn on the spot with both weapons held out, and both blades come round onto the target; a short hold.', ('flexible', 's4'): 'Circling lash. The weapon is swung in one full circle around the body and lashes the target as it comes round to the front; then it is drawn back.', ('sickle', 's2'): 'Low sweeping hook. The body drops low, the sickle sweeps round near the ground from the right to the front and hooks in; a short hold.', ('poleaxe', 's3'): 'Great spin. The upper body winds to the right; then one full turn on a low hop with the pole axe held out level, the axe head sweeping past the front; he lands facing forward.', ('bow', 's6'): 'Leaping shot. He crouches, jumps, draws the bow in the air and releases at the top of the jump; he lands and settles.', ('bow', 's4'): 'Three quick shots. He draws and releases three times in a row at three targets, turning the bow a little each time; then lowers it.'}.items():
    CLIP.setdefault(_f, {}).setdefault(_s, _t); CLIP[_f].setdefault('c' + _s[1:], CLIP[_f][_s])
for _f in CLIP:
    for _k in [k for k in CLIP[_f] if k[0] == 's']: CLIP[_f].setdefault('c' + _k[1:], CLIP[_f][_k])

def build(hid):
    name, family, weapon, desc, face, rear, pts, cloth, extra = H[hid]
    src = open(os.path.join(sm.WORK, 'sim', 'heroes.js'), encoding='utf-8').read(); row = next(h for h in json.loads(src[src.index('['):src.rindex(']') + 1]) if h['id'] == hid)
    assert row['family'] == family, (hid, row['family'], family)
    words = CLIP[family]; fill = lambda t: t % {'w': weapon} if '%(w)s' in t else t; mounted = family.startswith('mounted')
    tail = TAIL % weapon + (RIDER if mounted else ''); actions = {'idle': fill(words['idle']), 'move': fill(words['move'])}
    plain = lambda c: words[c] if c in words else words[c[1:]]      # pX = the clip X exactly as written (기본 병종): the same sentence
    for c in row['attacks'] + [row['skillClip']]: actions[c] = fill(plain(c)) + tail
    art = {'front': {'weapon butt': list(pts[0]), 'weapon tip': list(pts[1])}, 'left': {'weapon butt': list(pts[2]), 'weapon tip': list(pts[3])}, 'rear': {'weapon butt': list(pts[4]), 'weapon tip': list(pts[5])}}
    length = round(max(math.hypot(a[0] - b[0], a[1] - b[1]) for a, b in ((pts[0], pts[1]), (pts[2], pts[3]), (pts[4], pts[5]))))
    streamers = []
    for k in cloth: streamers += CLOTH[k] if isinstance(CLOTH[k], list) else [CLOTH[k]]
    cfg = {'hero': name, 'family': family, 'description': desc, 'face': face, 'rear_detail': rear,
           'guard_action': GUARD[family], 'actions': actions, 'weapon_length': length, 'weapon_grip': GRIP[family],
           'weapon_mode': 'bone' if family in ('bow', 'bow_long') else extra.get('mode', 'forward'), 'rear_hand': 'L' if family in ('bow', 'bow_long') else 'R', 'art_weapon': art, 'streamers': streamers}
    if mounted: cfg.update(body_scale=1.0, art_offset={'left': {'rider': [7, 0]}}, cloth_rgb=[[[0, 0], [0, 0], [0, 0]]])
    if extra.get('variety_ok'): cfg['variety_ok'] = extra['variety_ok']
    cfg['notes'] = ('2026-11-19 make_configs.py. 평타 %s, 전법 %s. 무기 좌표는 원화에서 눈으로 잰 값(±2px), 가려진 끝은 추정. ' % (' → '.join(row['attacks']), row['skillClip'])) + extra.get('note', '')
    return cfg

if __name__ == '__main__':
    force = '--force' in sys.argv; n = 0
    for hid in H:
        p = os.path.join(sm.WORK, 'art-in', hid, 'pixellab.json')
        if os.path.exists(p) and not force: continue
        cfg = build(hid)
        if os.path.exists(p):      # the canvas placement is measured by fit_canvas.py, not written here: keep it
            old = json.load(open(p, encoding='utf-8'))
            if 'canvas_offset' in old: cfg['canvas_offset'] = old['canvas_offset']
            for k in ('art', '_shortened', 'head'):      # written by shorten_shaft.py / by hand: an edited copy of the art and its measures
                if k in old: cfg[k] = old[k]
            if '_shortened' in old: cfg['art_weapon'] = old['art_weapon']; cfg['weapon_length'] = old['weapon_length']
        json.dump(cfg, open(p, 'w', encoding='utf-8', newline='\n'), ensure_ascii=False, indent=1); n += 1
    print('%d개 설정 파일 작성 (%d명 표)' % (n, len(H)))
